vec4 gold = vec4(0.8,0.7,0,0.5);
vec4 silv = vec4(0.8,0.8,0.8,0.5);
vec4 bron = vec4(0.66,0.32,0.15,0.5);
vec3 posa = vec3(1,0,0);
vec3 posb = vec3(0);
vec3 posc = vec3(-1,0,0);
float ra = 1.5;
float rb = .5;
float rc = .5;
vec3 light = vec3(0);
#define MAX_STEPS 100
#define MAX_DIST 100.
#define MIN_DIST 0.01
#define REF_DIST 0.02
bool or(bool a, bool b) {
    if(a) return a;
    else return b;
        }
mat3 matrot(vec3 xyz) {
    mat3 rx = mat3(vec3(1,0,0),vec3(0,-sin(xyz.x),cos(xyz.x)),vec3(0,cos(xyz.x),sin(xyz.x)));
    mat3 ry = mat3(vec3(cos(xyz.y),0,sin(xyz.y)),vec3(0,1,0),vec3(-sin(xyz.y),0,cos(xyz.y)));
    mat3 rz = mat3(vec3(cos(xyz.z),sin(xyz.z),0),vec3(-sin(xyz.z),cos(xyz.z),0),vec3(0,0,1));
    return rx * ry * rz;
        }
float smin( float a, float b, float k )
{
    k *= log(2.0);
    float x = b-a;
    return a + x/(1.0-exp2(x/k));
}
vec4 sdSphere(vec3 pos, vec3 cent, float r,vec3 col) {
    return vec4(length(pos-cent) - r,col);
        }
vec4 sdCube (vec3 pos,vec3 cent, vec3 size,vec3 col) {
    vec3 p = (abs(pos-cent) - size);
    return vec4(length(max(p,0.))+min(max(p.x,max(p.y,p.z)),0.),col);
        }
vec4 sdSquare (vec2 pos,vec2 cent, vec2 size,vec3 col) {
    vec2 p = abs(pos-cent) - size;
    return vec4(length(max(p,0.))+min(max(p.x,p.y),0.),col);
        }
vec4 sdRoCube (vec3 pos,vec3 cent, vec3 size,float ron,vec3 col) {
    float d = length(max(abs((pos-cent))-size,0.));
    return vec4(d-ron,col);
        }
vec4 sdTorus (vec3 pos,vec3 cent, vec2 r,vec3 col) {
    vec3 pc = pos - cent;
    vec3 rotpc = pc;
    float x = length(rotpc.xz) - r.x;
    return vec4(length(vec2(x,rotpc.y))-r.y,col);
        }
vec4 sdCapsule(vec3 pos,vec3 a, vec3 b, float r,vec3 col) {
    vec3 ab = b - a;
    vec3 ap = pos - a;

    float t = clamp(dot(ab,ap) / dot(ab,ab),0.,1.);
    vec3 c = a + t * ab;

    return vec4(length(pos-c) - r,col);
        }
vec4 Distance(vec3 pos) {
    vec4 spa = sdSphere(pos,posa,ra,bron.xyz);
    float a = spa.x;
    vec4 spb = sdSphere(pos,posb,rb,silv.xyz);
    float b = spb.x;
    vec4 spc = sdSphere(pos,posc,rc,gold.xyz);
    float c = spc.x;
    vec3 col = vec3(0);
    if(min(min(a,b),c) == a) col = spa.yzw;
    if(min(min(a,b),c) == b) col = spb.yzw;
    if(min(min(a,b),c) == c) col = spc.yzw;
    return vec4(min(min(a,b),c),col);
        }
bool RayMarchEx (vec3 ro, vec3 rd) {
    float dO = 0.;
    vec3 p = ro;
    vec4 po = Distance(p);
    vec3 col = vec3(0);
    for (int i = 0; i < MAX_STEPS; i++) {
        p = ro + rd * dO;
        po = Distance(p);
        float dS = po.x;
        dO += dS;
        if (dO > MAX_DIST) break;
        if (dS < MIN_DIST) break;
            }
    if (dO > MAX_DIST) return true;
    if (dO <= MAX_DIST) return false;
    }
vec4 RayMarch (vec3 ro, vec3 rd) {
    float dO = 0.;
    vec3 p = ro;
    vec4 po = Distance(p);
    vec3 col = vec3(0);
    for (int i = 0; i < MAX_STEPS; i++) {
        p = ro + rd * dO;
        po = Distance(p);
        float dS = po.x;
        dO += dS;
        if (dO > MAX_DIST) break;
        if (dS < MIN_DIST) break;
        if (length(p) < 1.5) po.yzw += vec3(1.);
            }
    if(or(po.x < MIN_DIST,length(p) < 1.5)) col = po.yzw;
    return vec4(dO,col);
    }
vec3 Normal(vec3 pos) {
    vec4 p = Distance(pos);
    float d = p.x;
    vec2 e = vec2 (0,0.01);
    vec4 yxx = Distance(pos-e.yxx);
    vec4 xyx = Distance(pos-e.xyx);
    vec4 xxy = Distance(pos-e.xxy);
    vec3 n = d - vec3(yxx.x,xyx.x,xxy.x);
    return normalize(n);
        }
vec3 Lighting (vec3 pos, vec3 lc) {
    vec3 l = normalize(light - pos);
    vec3 n = Normal(pos);
    vec4 d = RayMarch(pos + MIN_DIST * n * 2.,l);
    float dif = clamp(dot(l,n),0.,1.);

    if (d.x < length(pos-l)) dif *= (d.x/length(pos-l)) * .1;
    if (RayMarchEx(pos + MIN_DIST * n * 2.,l)) return dif * lc;
        }
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Setup
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(0);
    float bottom = -2.;
    float left = -2.;
    float right = 2.;
    float back = -2.;
    float front = 2.;
    vec3 sto = vec3(0);
    //Simulation
    vec3 vela = vec3(1,1,1);
    vec3 velb = vec3(1,1,1);
    vec3 velc = vec3(1,1,1);
    vec3 acc = vec3(0,0,-9.81);
    for (float i = 0.; i < 30.*iTime; i++) {
        posa += vela/30.;
        posb += velb/30.;
        posc += velc/30.;
        vela += acc/30.;
        velb += acc/30.;
        velc += acc/30.;
        if(posa.x < left+ra) vela.x *= -.98;
        if(posb.x < left+rb) velb.x *= -.98;
        if(posc.x < left+rc) velc.x *= -.98;

        if(posa.x > right-ra) vela.x *= -.98;
        if(posb.x > right-rb) velb.x *= -.98;
        if(posc.x > right-rc) velc.x *= -.98;

        if(posa.z < bottom+ra) vela.z *= -.98;
        if(posb.z < bottom+rb) velb.z *= -.98;
        if(posc.z < bottom+rc) velc.z *= -.98;

        if(posa.y > front-ra) vela.y *= -.98;
        if(posb.y > front-rb) velb.y *= -.98;
        if(posc.y > front-rc) velc.y *= -.98;

        if(posa.y > back+ra) vela.y *= -.98;
        if(posb.y > back+rb) velb.y *= -.98;
        if(posc.y > back+rc) velc.y *= -.98;
        if(distance(posa,posb)<ra+rb) {
            sto = vela;
            vela = -0.1 * reflect(vela-velb,normalize(posa-posb)) + velb;
            posa += (posa-posb)*ra/(ra+rb)*0.1;
            velb = -0.1 * reflect(velb-sto,normalize(posb-posa)) + sto;
            posb -= (posa-posb)*rb/(ra+rb)*0.1;
                }
        if(distance(posc,posb)<rc+rb) {
            sto = velc;
            vela = -0.1 * reflect(velc-velb,normalize(posc-posb)) + velb;
            posa += (posa-posb)*rc/(rc+rb)*0.1;
            velb = -0.1 * reflect(velb-sto,normalize(posb-posc)) + sto;
            posb -= (posc-posb)*rb/(rc+rb)*0.1;
                }
        if(distance(posc,posa)<rc+ra) {
            sto = velc;
            vela = -0.1 * reflect(velc-vela,normalize(posc-posa)) + vela;
            posa += (posa-posc)*rc/(rc+ra)*0.1;
            velb = -0.1 * reflect(vela-sto,normalize(posa-posc)) + sto;
            posb -= (posc-posa)*ra/(rc+ra)*0.1;
                }
            }
    //More Setup
    float focal = 1.;
    vec3 vr = vec3(0,0,0);
    mat3 rt = matrot(vr);
    vec3 ro = vec3(0,-5,0);
    vec3 rd = normalize(vec3(uv,focal));
    rd *= rt;
    vec3 r2d = rd;
    light = ro;
    vec3 p = vec3(0);
    vec3 n = vec3(0);
    vec3 r = vec3(0);
    float dif = 0.;
    //Rendering
    vec4 d = RayMarch(ro,rd);
    if (d.x < MAX_DIST) {
        p = ro + rd * d.x;
        n = Normal(p);
        r = reflect(rd,n);
        dif = length(Lighting(p,vec3(1)))/sqrt(3.);
            }
    vec4 ref = vec4(0);
    ref = RayMarch(p,r);
    col = vec3(dif);
    col *= d.yzw;
    vec4 re = RayMarch(p + Normal(p) * 0.01,reflect(rd,Normal(p)));
    p += reflect(rd,n) * re.y;
    if(d.yzw == gold.xyz) col = mix(col,  re.yzw, gold.w )*2.;
    if(d.yzw == silv.xyz) col = mix(col,  re.yzw, silv.w )*2.;
    if(d.yzw == bron.xyz) col = mix(col,  re.yzw, bron.w )*2.;
    // Output to screen
    fragColor = vec4(col,1.);
}
